#' Heatmap of the 3' UTR Shifts between Groups of Cells or along a Trajectory
#'
#' Global view of the alternative polyadenylation: for each gene, the relative 3' UTR length (usage of the isoforms
#' weighted by their 3' UTR length) in each group of cells (and sample), or in bins of cells ordered along a
#' trajectory (pseudotime), centered on the gene mean. Blue: 3' UTR shorter than the gene mean, red: longer.
#'
#' @param seurat_obj iDGE Seurat object generated by SCALPEL (features \code{gene***isoform}).
#' @param annotation_gr GTF \code{GRanges} (e.g. \code{rtracklayer::import("annotation.gtf.gz")}): 3' UTR length of
#'   the isoforms (UTR downstream of the CDS).
#' @param group_by Metadata column with the groups of cells (one column per group). With \code{order_by}, groups
#'   shown in an annotation bar above the bins.
#' @param sample_by Optional metadata column with the sample of each cell: one column per group and sample
#'   (replication of the shifts). Ignored with \code{order_by}.
#' @param groups Optional subset / order of the groups.
#' @param order_by Optional numeric metadata column (e.g. pseudotime): cells ordered by this value and pooled in
#'   \code{n_bins} bins of the same number of cells (one column per bin).
#' @param n_bins Number of bins of cells with \code{order_by}. Default 30.
#' @param genes Optional genes: vector of gene names, or the table of \code{FindIsoforms} (genes with a tandem 3' UTR
#'   event). Default: all the genes with isoforms of different 3' UTR lengths.
#' @param n_genes Maximum number of genes shown: genes with the highest variation of their relative 3' UTR length
#'   between the columns. Default 100.
#' @param min_umis Minimum number of gene UMIs in a column (fewer: no value, gray). Default 20.
#' @param scale If \code{TRUE} (default), relative 3' UTR lengths scaled per gene (z-score, capped at +/- 2);
#'   otherwise centered on the gene mean.
#' @param n_clusters Optional number of clusters of genes (hierarchical clustering of the values): genes split in
#'   blocks (e.g. early / late shortening, lengthening), cluster of each gene in \code{attr(p, "shift")}.
#' @param show_genes Show the gene names (default: if 60 genes or less).
#' @param assay Seurat assay. Default \code{"RNA"}.
#'
#' @details
#' The relative 3' UTR length of a gene in a column is the weighted 3' UTR length of its isoforms (counts of the cells
#' of the column) rescaled between its shortest (0) and longest (1) isoform 3' UTR. Isoforms without CDS are not
#' used. Genes are clustered (groups) or ordered by the bin of their longest 3' UTR (\code{order_by}). The table of
#' values is available in \code{attr(p, "shift")}.
#'
#' @return A ggplot (patchwork with \code{order_by} and \code{group_by}) object.
#'
#' @examples
#' \dontrun{
#' gtf = rtracklayer::import("gencode.vM23.annotation.gtf.gz")
#' plotShiftHeatmap(idge, annotation_gr = gtf, group_by = "celltype", sample_by = "orig.ident", genes = diu.table)
#' plotShiftHeatmap(idge, annotation_gr = gtf, group_by = "celltype", order_by = "pseudotime", genes = diu.table)
#' }
#'
#' @export
plotShiftHeatmap <- function(
    seurat_obj,
    annotation_gr,
    group_by = NULL,
    sample_by = NULL,
    groups = NULL,
    order_by = NULL,
    n_bins = 30,
    genes = NULL,
    n_genes = 100,
    min_umis = 20,
    scale = TRUE,
    n_clusters = NULL,
    show_genes = NULL,
    assay = "RNA") {
  meta <- seurat_obj[[]]
  if (is.null(group_by) & is.null(order_by)) stop("Error: provide group_by and / or order_by !")
  for (v in c(group_by, sample_by, order_by)) if (!(v %in% colnames(meta))) stop("Error: ", v, " not found in Seurat object !")

  #- cells & columns of the heatmap: groups (x samples) or bins along order_by...
  key <- data.table::data.table(cell = colnames(seurat_obj))
  if (!is.null(group_by)) key[, group := as.character(meta[[group_by]])]
  keep <- rep(TRUE, nrow(key))
  if (!is.null(group_by)) keep <- !is.na(key$group) & (is.null(groups) | key$group %in% groups)
  if (!is.null(order_by)) {
    key[, t := as.numeric(meta[[order_by]])]
    keep <- keep & !is.na(key$t)
    key <- key[keep]
    key[, column := as.integer(cut(rank(t, ties.method = "first"), n_bins, labels = FALSE))]
  } else {
    key <- key[keep]
    key[, sample := if (is.null(sample_by)) "all" else as.character(meta[[sample_by]][keep])]
    key[, column := paste(group, sample, sep = "\r")]
  }
  key[, column := factor(column, levels = sort(unique(column)))]

  #- isoforms with a 3' UTR length, genes with isoforms of different 3' UTR lengths...
  utr <- .utr3_length(annotation_gr)
  counts <- SeuratObject::LayerData(SeuratObject::JoinLayers(seurat_obj, assay = assay), assay = assay, layer = "counts")
  feats <- data.table::data.table(gene_tr = rownames(counts))
  feats[, c("gene_name", "transcript_name") := data.table::tstrsplit(gene_tr, "***", fixed = TRUE)]
  feats <- merge(feats, utr, by = c("gene_name", "transcript_name"), sort = FALSE)
  if (!is.null(genes)) {
    if (is.data.frame(genes)) {
      genes <- data.table::as.data.table(genes)
      if ("event_type" %in% colnames(genes)) genes <- genes[event_type == "tandem_3UTR"]
      genes <- unique(genes$gene_name)
    }
    feats <- feats[gene_name %in% genes]
  }
  feats[, `:=`(min_len = min(UTRlength), max_len = max(UTRlength)), by = gene_name]
  feats <- feats[max_len > min_len]
  if (nrow(feats) == 0) stop("No gene with isoforms of different 3' UTR lengths !")

  #- pseudo-bulk counts per column: gene UMIs & weighted 3' UTR length...
  idx <- match(key$cell, colnames(counts))
  x <- counts[feats$gene_tr, idx, drop = FALSE]
  C <- Matrix::sparseMatrix(i = seq_along(key$column), j = as.integer(key$column), x = 1, dims = c(nrow(key), nlevels(key$column)))
  gf <- factor(feats$gene_name)
  A <- Matrix::sparseMatrix(i = as.integer(gf), j = seq_along(gf), x = 1, dims = c(nlevels(gf), length(gf)))
  tot <- as.matrix(A %*% x %*% C)
  wlen <- as.matrix(A %*% (x * feats$UTRlength) %*% C)
  rng <- unique(feats[, .(gene_name, min_len, max_len)])[match(levels(gf), gene_name)]
  rel <- (wlen / pmax(tot, 1e-12) - rng$min_len) / (rng$max_len - rng$min_len)
  rel[tot < min_umis] <- NA
  dimnames(rel) <- list(levels(gf), levels(key$column))

  #- genes with values in >= 80% of the columns, the most variable ones...
  rel <- rel[rowMeans(!is.na(rel)) >= .8, , drop = FALSE]
  if (nrow(rel) == 0) stop("No gene with enough UMIs (min_umis) in the columns !")
  v <- apply(rel, 1, stats::sd, na.rm = TRUE)
  rel <- rel[order(-v)[seq_len(min(n_genes, nrow(rel)))], , drop = FALSE]
  val <- rel - rowMeans(rel, na.rm = TRUE)
  if (scale) val <- pmin(pmax(val / pmax(apply(rel, 1, stats::sd, na.rm = TRUE), 1e-12), -2), 2)
  lim <- if (scale) 2 else max(abs(val), na.rm = TRUE)

  #- order of the genes: clustering (groups) or bin of the longest 3' UTR (trajectory), optional clusters...
  v0 <- val
  v0[is.na(v0)] <- 0
  hc <- if (nrow(v0) >= 2) stats::hclust(stats::dist(v0), method = "ward.D2") else NULL
  clusters <- if (!is.null(n_clusters) & !is.null(hc)) stats::cutree(hc, k = min(n_clusters, nrow(v0))) else stats::setNames(rep(1L, nrow(v0)), rownames(v0))
  if (!is.null(order_by)) {
    sm <- t(apply(v0, 1, function(r) stats::filter(r, rep(1 / 3, 3), sides = 2)))
    sm[is.na(sm)] <- v0[is.na(sm)]
    peak <- apply(sm, 1, which.max)
    #- clusters ordered by their mean peak, genes by their peak...
    cl_peak <- tapply(peak, clusters, mean)
    lv_genes <- rownames(v0)[order(cl_peak[as.character(clusters)], peak, -apply(sm, 1, max))]
  } else {
    lv_genes <- if (!is.null(hc)) rownames(v0)[hc$order] else rownames(v0)
  }
  #- clusters numbered from the top of the heatmap...
  clusters <- stats::setNames(match(clusters, unique(clusters[lv_genes])), names(clusters))

  #- long table...
  tab <- data.table::as.data.table(reshape2::melt(val, varnames = c("gene_name", "column"), value.name = "value"))
  tab[, umis := as.vector(tot[match(rownames(val), levels(gf)), , drop = FALSE])]
  tab[, rel_3UTR := as.vector(rel)]
  tab[, cluster := clusters[as.character(gene_name)]]
  tab[, gene_name := factor(as.character(gene_name), levels = rev(lv_genes))]
  ncl <- tab[, .(n = data.table::uniqueN(gene_name)), by = cluster]
  tab[, cluster := factor(cluster, levels = sort(ncl$cluster), labels = paste0(sort(ncl$cluster), " (", ncl$n[order(ncl$cluster)], ")"))]
  row_facet <- !is.null(n_clusters) && nlevels(tab$cluster) > 1
  if (is.null(show_genes)) show_genes <- length(lv_genes) <= 60
  fill <- ggplot2::scale_fill_gradient2(low = "#2166AC", mid = "white", high = "#B2182B", midpoint = 0, limits = c(-lim, lim),
                                        oob = scales::squish, na.value = "gray85",
                                        name = paste0("relative\n3' UTR length\n", if (scale) "(z-score)" else "(centered)"))
  th <- ggplot2::theme_minimal(base_size = 12) +
    ggplot2::theme(panel.grid = ggplot2::element_blank(), axis.text.y = if (show_genes) ggplot2::element_text(face = "italic", size = 8) else ggplot2::element_blank(),
                   plot.title = ggplot2::element_text(face = "bold"))
  ttl <- paste0("3' UTR shifts (", length(lv_genes), " genes)")

  if (is.null(order_by)) {
    tab[, c("group", "sample") := data.table::tstrsplit(as.character(column), "\r", fixed = TRUE)]
    tab[, group := factor(group, levels = if (is.null(groups)) sort(unique(group)) else groups)]
    p <- ggplot2::ggplot(tab, ggplot2::aes(sample, gene_name, fill = value)) +
      ggplot2::geom_tile() + fill + th +
      ggplot2::facet_grid(if (row_facet) cluster ~ group else . ~ group, scales = "free", space = "free", labeller = ggplot2::label_wrap_gen(15)) +
      ggplot2::labs(x = NULL, y = NULL, title = ttl) +
      ggplot2::theme(axis.text.x = if (is.null(sample_by)) ggplot2::element_blank() else ggplot2::element_text(angle = 45, hjust = 1),
                     strip.text = ggplot2::element_text(face = "bold"), strip.text.y = ggplot2::element_text(angle = 0),
                     panel.spacing = ggplot2::unit(.3, "lines"))
  } else {
    tab[, column := as.integer(as.character(column))]
    p <- ggplot2::ggplot(tab, ggplot2::aes(column, gene_name, fill = value)) +
      ggplot2::geom_tile() + fill + th +
      ggplot2::scale_x_continuous(expand = c(0, 0)) +
      ggplot2::labs(x = paste0(order_by, " (bins of ", round(nrow(key) / n_bins), " cells)"), y = NULL) +
      ggplot2::theme(axis.text.x = ggplot2::element_blank(), strip.text.y = ggplot2::element_text(angle = 0, face = "bold"),
                     panel.spacing = ggplot2::unit(.3, "lines"))
    if (row_facet) p <- p + ggplot2::facet_grid(cluster ~ ., scales = "free_y", space = "free_y")
    if (!is.null(group_by)) {
      #- annotation bar: fraction of the cells of each group in each bin...
      ann <- key[, .N, by = .(column, group)][, frac := N / sum(N), by = column]
      ann[, column := as.integer(as.character(column))]
      ann[, group := factor(group, levels = if (is.null(groups)) sort(unique(group)) else groups)]
      pa <- ggplot2::ggplot(ann, ggplot2::aes(column, frac, fill = group)) +
        ggplot2::geom_col(width = 1) +
        ggplot2::scale_fill_manual(values = stats::setNames(.group_colors(nlevels(ann$group)), levels(ann$group)), name = group_by) +
        ggplot2::scale_x_continuous(expand = c(0, 0)) + ggplot2::scale_y_continuous(expand = c(0, 0)) +
        ggplot2::labs(x = NULL, y = NULL, title = ttl) +
        ggplot2::theme_void(base_size = 12) + ggplot2::theme(plot.title = ggplot2::element_text(face = "bold"))
      p <- patchwork::wrap_plots(pa, p, ncol = 1, heights = c(.06, 1), guides = "collect")
    } else {
      p <- p + ggplot2::ggtitle(ttl)
    }
  }
  attr(p, "shift") <- tab
  return(p)
}

#- 3' UTR length of each coding transcript: UTR segments downstream of the CDS end (GTF GRanges)
.utr3_length <- function(annotation_gr) {
  annotation_gr[annotation_gr$type == "CDS" | annotation_gr$type == "UTR"][, c("type", "gene_name", "transcript_name")] %>%
    data.frame() %>%
    dplyr::distinct(seqnames, start, end, strand, type, width, gene_name, transcript_name) %>%
    dplyr::group_by(transcript_name) %>%
    dplyr::filter(any(type == "CDS")) %>%
    dplyr::mutate(end_CDS = dplyr::if_else(strand == "-", min(start[which(type == "CDS")]), max(end[which(type == "CDS")]))) %>%
    dplyr::filter((strand == "-" & end < end_CDS) | (strand == "+" & start > end_CDS)) %>%
    dplyr::mutate(UTRlength = sum(width)) %>%
    dplyr::ungroup() %>%
    dplyr::distinct(gene_name, transcript_name, UTRlength) %>%
    dplyr::mutate(gene_name = gsub("_", "-", gene_name), transcript_name = gsub("_", "-", transcript_name)) %>%
    data.table::data.table()
}
